mapper.select:
SELECT c.calc_id, c.emp_id, c.calc_month, c.basic_salary, c.post_allowance, c.overtime_salary, c.leave_deduct, c.absent_deduct, c.total_income, c.social_security, c.provident_fund, c.personal_tax, c.net_salary, c.calc_status, c.create_time, c.update_time, COALESCE(e.emp_code, '') AS emp_code, COALESCE(e.emp_name, '') AS emp_name FROM hr_sal_calculate c LEFT JOIN sys_emp e ON c.emp_id = e.emp_id WHERE 1=1
AND c.emp_id = #{empId}
AND e.emp_code LIKE CONCAT('%', #{empCode}, '%')
AND e.emp_name LIKE CONCAT('%', #{empName}, '%')
AND c.calc_month = #{calcMonth}
AND c.calc_status = #{calcStatus}
ORDER BY c.calc_month DESC, c.create_time DESC

mapper.update:
UPDATE hr_sal_calculate
basic_salary = #{basicSalary}, post_allowance = #{postAllowance}, overtime_salary = #{overtimeSalary}, leave_deduct = #{leaveDeduct}, absent_deduct = #{absentDeduct}, total_income = #{totalIncome}, social_security = #{socialSecurity}, provident_fund = #{providentFund}, personal_tax = #{personalTax}, net_salary = #{netSalary}, calc_status = #{calcStatus},
WHERE calc_id = #{calcId}
